        if current_user not in group_data["members"]:
            raise HTTPException(
                status_code=403,
                detail="Not a member of this group",
            )

        if conv is None:
            prompt_count = 1

            conv_record = create_conversation(
                db,
                {
                    "groupId": group_id,
                    "userName": current_user,
                    "promptCount": prompt_count,
                    "status": "pending",
                },
            )

            conversation_id = conv_record["id"]
            existing_messages = []

        else:
            prompt_count = conv["promptCount"] + 1

            update_conversation(
                db,
                conversation_id,
                {"promptCount": prompt_count},
            )

            existing_messages = conv["messages"]

        add_conversation_message(
            db,
            conversation_id,
            "user",
            message_text,
        )

        if prompt_count > MAX_PROMPTS_PER_CONVERSATION:
            reason = (
                f"Prompt limit exceeded "
                f"(maximum {MAX_PROMPTS_PER_CONVERSATION} prompts). "
                "Please enter this expense manually."
            )

            add_conversation_message(
                db,
                conversation_id,
                "assistant",
                reason,
            )

            update_conversation(
                db,
                conversation_id,
                {"status": "unsuccessful"},
            )

            return {
                "type": "unresolved",
                "reason": reason,
                "conversationId": conversation_id,
                "promptCount": prompt_count,
                "status": "unsuccessful",
                "fallback": "manual",
            }

        full_messages = existing_messages + [
            {"role": "user", "content": message_text}
        ]

        active_llm = get_llm()

        result = parse_turn(
            llm=active_llm,
            conversation=full_messages,
            roster=group_data["members"],
            current_user=current_user,
        )

        res_type = result.get("type")

        if res_type == "question":
            question_text = result["question"]

            add_conversation_message(
                db,
                conversation_id,
                "assistant",
                question_text,
            )

            update_conversation(
                db,
                conversation_id,
                {"status": "pending"},
            )

            return {
                "type": "question",
                "question": question_text,
                "conversationId": conversation_id,
                "promptCount": prompt_count,
                "status": "pending",
            }

        elif res_type == "preview":
            preview = result["preview"]

            add_conversation_message(
                db,
                conversation_id,
                "assistant",
                "Validated preview generated.",
            )

            update_conversation(
                db,
                conversation_id,
                {
                    "status": "preview",
                    "finalPreview": preview,
                },
            )

            return {
                "type": "preview",
                "preview": preview,
                "conversationId": conversation_id,
                "promptCount": prompt_count,
                "status": "preview",
            }

        elif res_type == "unresolved":
            reason = result.get(
                "reason",
                "Unable to parse expense.",
            )

            add_conversation_message(
                db,
                conversation_id,
                "assistant",
                reason,
            )

            update_conversation(
                db,
                conversation_id,
                {"status": "unresolved"},
            )

            return {
                "type": "unresolved",
                "reason": reason,
                "conversationId": conversation_id,
                "promptCount": prompt_count,
                "status": "unresolved",
                "fallback": "manual",
            }

        else:
            err_msg = result.get(
                "message",
                "Unexpected error processing expense.",
            )

            add_conversation_message(
                db,
                conversation_id,
                "assistant",
                err_msg,
            )

            return {
                "type": "error",
                "message": err_msg,
                "conversationId": conversation_id,
                "promptCount": prompt_count,
                "status": "error",
            }

